#!/usr/bin/env python3
"""srctok25.py — общий разбор текста для сверки предложений с источниками (srcidx25.py, srcsent25.py).
Слово превращается в основу (первые 4–5 букв), числительные словами («пятнадцати суток», «от одной тысячи до двух тысяч»,
«трёхдневный») — в числа цифрами, чтобы «15 суток» в ответе сравнивалось с «пятнадцати суток» в законе."""
import re
U = {}
def _add(v, *ws):
    for w in ws: U[w] = v
_add(1, 'один', 'одна', 'одно', 'одного', 'одной', 'одному', 'одним', 'одном', 'одну')
_add(2, 'два', 'две', 'двух', 'двум', 'двумя'); _add(3, 'три', 'трех', 'трем', 'тремя'); _add(4, 'четыре', 'четырех', 'четырем', 'четырьмя')
_add(5, 'пять', 'пяти', 'пятью'); _add(6, 'шесть', 'шести', 'шестью'); _add(7, 'семь', 'семи'); _add(8, 'восемь', 'восьми'); _add(9, 'девять', 'девяти')
_add(10, 'десять', 'десяти', 'десятью')
for v, s in ((11, 'одиннадцат'), (12, 'двенадцат'), (13, 'тринадцат'), (14, 'четырнадцат'), (15, 'пятнадцат'), (16, 'шестнадцат'), (17, 'семнадцат'),
             (18, 'восемнадцат'), (19, 'девятнадцат'), (20, 'двадцат'), (30, 'тридцат')): _add(v, s + 'ь', s + 'и', s + 'ью')
_add(40, 'сорок', 'сорока'); _add(50, 'пятьдесят', 'пятидесяти'); _add(60, 'шестьдесят', 'шестидесяти'); _add(70, 'семьдесят', 'семидесяти')
_add(80, 'восемьдесят', 'восьмидесяти'); _add(90, 'девяносто', 'девяноста'); _add(100, 'сто', 'ста')
_add(200, 'двести', 'двухсот'); _add(300, 'триста', 'трехсот'); _add(400, 'четыреста', 'четырехсот'); _add(500, 'пятьсот', 'пятисот')
_add(600, 'шестьсот', 'шестисот'); _add(700, 'семьсот', 'семисот'); _add(800, 'восемьсот', 'восьмисот'); _add(900, 'девятьсот', 'девятисот')
M = {'тысяча': 1000, 'тысячи': 1000, 'тысяч': 1000, 'тысячу': 1000, 'миллион': 10 ** 6, 'миллиона': 10 ** 6, 'миллионов': 10 ** 6}
PREF = re.compile(r'\b(двух|трех|четырех|пяти|шести|семи|восьми|девяти|десяти|пятнадцати|двадцати|тридцати|сорока|шестидесяти|девяноста)'
                  r'(дневн|суточн|месячн|летн|кратн|часов|недельн|годичн)')
TOK = re.compile(r'[а-яa-z]+|\d+|[,;.:()«»]')
def prep(t):
    t = t.lower().replace('ё', 'е')
    t = re.sub(r'(?<=[а-я])[-\u00ad]\s*\n\s*(?=[а-я])', '', t)              # перенос слова в PDF
    t = re.sub(r'(?<=\d)[ \u00a0\u202f](?=\d{3}(?!\d))', '', t)              # 1 000 → 1000
    return PREF.sub(r'\1 \2', t)
def stem(w): return w[:5] if len(w) > 6 else w[:4]
def tokens(t, pos=False):
    """основы слов (от 4 букв) и числа цифрами, в порядке текста; pos=True — пары (основа, место в prep(t))"""
    out = []; tot = cur = 0; last = None; open_ = False; p0 = 0
    def flush():
        nonlocal tot, cur, last, open_
        if open_: out.append((str(tot + cur), p0) if pos else str(tot + cur))
        tot = cur = 0; last = None; open_ = False
    comb = lambda a, v: (a >= 100 and v < 100) or (20 <= a < 100 and a % 10 == 0 and v < 10)
    for m in TOK.finditer(prep(t)):
        w = m.group()
        if w in U:
            v = U[w]
            if open_ and last is not None and not comb(last, v): flush()
            if not open_: p0 = m.start()
            cur += v; last = v; open_ = True
        elif w in M:
            if not open_: p0 = m.start()
            cur = (cur or 1) * M[w]; tot += cur; cur = 0; last = None; open_ = True
        else:
            flush()
            if w[0].isdigit(): out.append((w, m.start()) if pos else w)
            elif not w[0].isalpha(): pass
            elif len(w) >= 4: out.append((stem(w), m.start()) if pos else stem(w))
    flush(); return out
CLEAN = re.compile(r'\((?:В редакции|Дополнен|Абзац|Пункт|Часть|Подпункт|Статья|Наименование|Утратил|Введен|Изменен|в ред\.|введен|введена|часть|пункт|абзац|п\.|ч\.)[^()]{0,400}\)')
ART = re.compile(r'Статья\s+(\d+(?:\.\d+)*(?:\s\d)?)\s?\.\s+(?=[А-ЯЁ(])')
def segments(path):
    """текст источника по статьям: [(номер статьи цифрами подряд или '', текст)]"""
    raw = open(path, encoding='utf-8', errors='replace').read()
    raw = re.sub(r'<\d+>', ' ', raw); raw = CLEAN.sub(' ', raw)
    segs = []; p = 0; cur = ''
    for m in ART.finditer(raw):
        segs.append((cur, raw[p:m.start()])); p = m.start(); cur = re.sub(r'\D', '', m.group(1))
    segs.append((cur, raw[p:])); return segs
SPLIT = re.compile(r'(?<=[.!?…»)])\s+(?=[А-ЯЁ«*])')
def sentences(line):
    out = []; cur = ''
    for p in SPLIT.split(line):
        cur = (cur + ' ' + p) if cur else p
        if cur.count('«') <= cur.count('»') and cur.count('//') % 2 == 0 and cur.count('(') <= cur.count(')') and not re.search(r'(?:^|\s)(?:ст|ч|п|пп|подп|гл|абз|т|см|им|г|гг|др|руб|тыс|млн|д|е|н|примеч)\.$', cur):
            out.append(cur); cur = ''
    if cur: out.append(cur)
    return out
REFNUM = re.compile(r'(?:стать[а-я]*|ст\.|част[а-я]*|ч\.|пункт[а-я]*|п\.|пп\.|подп\.|подпункт[а-я]*|глав[а-я]*|гл\.|раздел[а-я]*|абз\.|абзац[а-я]*|примечани[а-я]*|приложени[а-я]*|№)\s*\d+(?:\.\d+)*(?:\s*(?:,|и|–|—|-)\s*\d+(?:\.\d+)*)*', re.I)
def strip(s):
    s = re.sub(r'//.+?//', ' ', s); s = REFNUM.sub(' ', s); s = re.sub(r'\d{1,2}\.\d{2}\.\d{4}', ' ', s)
    s = re.sub(r'^\s*(?:[-–>]\s*)?(?:\*\*)?\d+[.)]\s', ' ', s); s = re.sub(r'\b(?:19|20)\d\d\s*(?:г\.|год[а-я]*)', ' ', s)
    return s.replace('**', ' ')
if __name__ == '__main__':
    for s in ('штраф от одной тысячи до двух тысяч пятисот рублей или арест на срок до пятнадцати суток', 'в трёхдневный срок; не позднее 3 часов; 1 000 рублей',
              'двадцать пять дней, сто двадцать часов, сорок восемь часов, двух тысяч, одной тысячи пятисот'): print(tokens(s))
